{
  "predictors": [
    {
      "name": "Employee Satisfaction Index",
      "construction": "Average employee satisfaction score from annual company surveys, scaled by total number of employees.",
      "rationale": "Firms with higher employee satisfaction may have more productive workforces, leading to better financial performance.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Environmental Innovation Score",
      "construction": "Total R&D expenditure on environmentally sustainable technologies over the last year divided by total assets.",
      "rationale": "Companies investing in sustainable technologies may gain competitive advantages in efficiency and regulatory compliance.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Customer Retention Ratio",
      "construction": "Percentage change in customer base size over the last year, adjusted for churn rates.",
      "rationale": "Companies with higher customer retention may have stronger brand loyalty, leading to sustained revenues.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Patent Citation Impact",
      "construction": "Number of citations per patent filed over the past three years, scaled by the firm's R&D expenditure.",
      "rationale": "Firms with highly cited patents are likely leaders in innovation, potentially translating to market success.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Social Media Sentiment Score",
      "construction": "Net positive mentions of the firm on major social media platforms over the past quarter, scaled by total mentions.",
      "rationale": "Positive social media sentiment may reflect favorable consumer perceptions and potential sales growth.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Board Diversity Index",
      "construction": "Proportion of board members from underrepresented demographics.",
      "rationale": "Diverse boards may provide a broader range of perspectives, leading to better strategic decisions.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Supply Chain Efficiency Ratio",
      "construction": "Total cost savings from supply chain improvements over the last year divided by total cost of goods sold.",
      "rationale": "Efficient supply chains can reduce costs and improve margins, leading to higher profitability.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Market Adaptability Score",
      "construction": "Speed of deployment of new products/services measured by time from R&D completion to market launch, scaled by industry average.",
      "rationale": "Firms that rapidly adapt to market changes are likely to capture new growth opportunities.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Cybersecurity Investment Ratio",
      "construction": "Annual expenditure on cybersecurity measures divided by total IT budget.",
      "rationale": "Investments in cybersecurity can prevent costly breaches and protect consumer trust.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Executive Tenure Stability",
      "construction": "Standard deviation of tenure lengths of top executives.",
      "rationale": "Stable executive teams may better implement long-term strategies and avoid disruptive turnover.",
      "higher_returns_for": "low values of the measure"
    }
  ]
}
